challenge_result.investigation_instruction:
{
  "plans": [
    {
      "hypothesis_id": "h1",
      "hypothesis_statement": "pcscf is the source of the anomalous SIP REGISTER rates and the resulting downstream UPF media activity collapse.",
      "primary_suspect_nf": "pcscf",
      "probes": [
        {
          "tool": "measure_rtt",
          "args_hint": "measure_rtt('pcscf', icscf_ip) to check transport reachability from pcscf.",
          "expected_if_hypothesis_holds": "High packet loss or elevated latency is observed on the path from pcscf to icscf.",
          "falsifying_observation": "0% packet loss and normal latency is observed.",
          "conflates_with": [
            "icscf network interface",
            "network path between pcscf and icscf"
          ]
        },
        {
          "tool": "measure_rtt",
          "args_hint": "measure_rtt('rtpengine', pcscf_ip) to test pcscf from a different source.",
          "expected_if_hypothesis_holds": "High packet loss or elevated latency is observed, corroborating that the deviation belongs to pcscf.",
          "falsifying_observation": "0% packet loss and normal latency is observed, indicating the original reading was attributable to one of the conflated entries, not pcscf.",
          "conflates_with": []
        },
        {
          "tool": "run_kamcmd",
          "args_hint": "run_kamcmd('pcscf', 'dlg.list') to show active dialogs directly.",
          "expected_if_hypothesis_holds": "Value drops to 0 or significantly decreases.",
          "falsifying_observation": "Value remains stable at ~1 per active VoNR call.",
          "conflates_with": []
        }
      ],
      "notes": "Using KB-curated metric candidates and partner probes to isolate pcscf."
    },
    {
      "hypothesis_id": "h2",
      "hypothesis_statement": "upf is the source of the gtp_outdatapktn3upf_per_ue spike and the activity during calls collapse.",
      "primary_suspect_nf": "upf",
      "probes": [
        {
          "tool": "measure_rtt",
          "args_hint": "measure_rtt('upf', rtpengine_ip) to verify the media forwarding path.",
          "expected_if_hypothesis_holds": "High packet loss or elevated latency is observed on the path from upf to rtpengine.",
          "falsifying_observation": "The metric stays at its healthy baseline.",
          "conflates_with": [
            "rtpengine network interface",
            "network path between upf and rtpengine"
          ]
        },
        {
          "tool": "measure_rtt",
          "args_hint": "measure_rtt('amf', upf_ip) to test upf from a different source.",
          "expected_if_hypothesis_holds": "High packet loss or elevated latency is observed, corroborating that the deviation belongs to upf.",
          "falsifying_observation": "The probe's reading is inconsistent with upf being the source (e.g. the metric stays at its healthy baseline).",
          "conflates_with": []
        },
        {
          "tool": "get_dp_quality_gauges",
          "args_hint": "window_seconds=120 to check upf.activity_during_calls.",
          "expected_if_hypothesis_holds": "Active calls are reported but no media is flowing, resulting in a drop in activity_during_calls.",
          "falsifying_observation": "The value remains at ~1.0, indicating traffic fully follows active calls.",
          "conflates_with": []
        }
      ],
      "notes": "Partner probe added for compositional measure_rtt tool, layer scoping removed from expected texts."
    },
    {
      "hypothesis_id": "h3",
      "hypothesis_statement": "icscf is the source of the downstream REGISTER and CDP reply rate drops.",
      "primary_suspect_nf": "icscf",
      "probes": [
        {
          "tool": "measure_rtt",
          "args_hint": "measure_rtt('icscf', scscf_ip) to check transport reachability from icscf.",
          "expected_if_hypothesis_holds": "High packet loss or elevated latency is observed on the path from icscf to scscf.",
          "falsifying_observation": "0% packet loss and normal latency is observed.",
          "conflates_with": [
            "scscf network interface",
            "network path between icscf and scscf"
          ]
        },
        {
          "tool": "measure_rtt",
          "args_hint": "measure_rtt('pcscf', icscf_ip) to test icscf from a different source.",
          "expected_if_hypothesis_holds": "High packet loss or elevated latency is observed, corroborating that the deviation belongs to icscf.",
          "falsifying_observation": "0% packet loss and normal latency is observed, indicating the original reading was attributable to one of the conflated entries, not icscf.",
          "conflates_with": []
        },
        {
          "tool": "run_kamcmd",
          "args_hint": "run_kamcmd('icscf', 'stats.fetch ims_icscf:uar_timeouts')",
          "expected_if_hypothesis_holds": "A spike in UAR timeouts is observed.",
          "falsifying_observation": "Value remains at 0.",
          "conflates_with": []
        }
      ],
      "notes": "Includes composition disambiguation partner probe for measure_rtt."
    }
  ]
}
